import{linear,inverseLinear,rotate,midpointSquare,geometricSum,mean,median,choose,modulo,graphEdges,shortestPath}from'./extended-math.js';
const C={blue:'#93b9fa',mint:'#b4f2d5',amber:'#efbd81',pink:'#ef96ba',purple:'#c1a0f5',white:'#edf2f6',muted:'#8e9eb3',grid:'#203046'};
function clipped(exp,fn){const p=exp.plot,c=exp.ctx;c.save();c.beginPath();c.rect(p.left,p.top,p.width,p.height);c.clip();fn();c.restore()}
function footer(exp,text){exp.text(text,exp.w/2,exp.h-36,C.white,exp.w<450?11:14,'center')}
function regular(n,angle,r,cx,cy){return Array.from({length:n},(_,i)=>{const t=(i/n*360+angle-90)*Math.PI/180;return[cx+Math.cos(t)*r,cy+Math.sin(t)*r]})}
export const extraRenderers={
functions(){const{a,b,x}=this.v,xy=this.chart(-4,4,-10,10);clipped(this,()=>{this.line([xy(-4,linear(-4,a,b)),xy(4,linear(4,a,b))],C.mint,3);this.line([xy(x,0),xy(x,linear(x,a,b)),xy(0,linear(x,a,b))],C.blue,1,[4,4]);this.dot(...xy(x,linear(x,a,b)),C.blue,7)});footer(this,`x = ${x.toFixed(1)}     y = ${linear(x,a,b).toFixed(2)}`)},
inverse(){const{a,b,x}=this.v,xy=this.chart(-5,5,-5,5);clipped(this,()=>{this.line([xy(-5,-5),xy(5,5)],C.muted,1,[4,4]);this.line([xy(-5,linear(-5,a,b)),xy(5,linear(5,a,b))],C.blue,2.5);this.line([xy(-5,inverseLinear(-5,a,b)),xy(5,inverseLinear(5,a,b))],C.amber,2.5);const y=linear(x,a,b);this.line([xy(x,y),xy(y,x)],C.mint,1,[3,3]);this.dot(...xy(x,y),C.blue,6);this.dot(...xy(y,x),C.amber,6)});footer(this,'Blue: original     Amber: inverse     Dashed: y = x')},
exponential(){const{r,n}=this.v,max=Math.max(4,r**Math.max(1,n)*1.1),left=40,width=this.w-75,top=40,height=this.h-125;this.line([[left,top],[left,top+height],[left+width,top+height]],C.muted,1);this.text(max.toFixed(0),left-5,top,C.muted,10,'right');const points=[];for(let i=0;i<=n;i++){const x=left+i/Math.max(1,n)*width,y=top+height-(r**i)/max*height;points.push([x,y]);this.dot(x,y,C.amber,4);this.text(String(i),x,top+height+18,C.muted,11,'center')}this.line(points,C.amber,2);footer(this,`${n} rounds     ${r.toFixed(1)}ⁿ = ${(r**n).toFixed(2)}`)},
unitcircle(){const t=this.v.angle*Math.PI/180,r=Math.min(this.w*.28,(this.h-110)*.42),cx=this.w*.43,cy=(this.h-65)/2+10,c=this.ctx;this.line([[cx-r-20,cy],[cx+r+25,cy]],C.grid);this.line([[cx,cy-r-20],[cx,cy+r+20]],C.grid);c.beginPath();c.arc(cx,cy,r,0,Math.PI*2);c.strokeStyle=C.muted;c.lineWidth=1.5;c.stroke();const x=cx+r*Math.cos(t),y=cy-r*Math.sin(t);this.line([[cx,cy],[x,cy]],C.blue,4);this.line([[x,cy],[x,y]],C.amber,4);this.line([[cx,cy],[x,y]],C.mint,2);this.dot(x,y,C.mint,6);this.text('1',cx+r+12,cy+4,C.muted,11);footer(this,`cos ${this.v.angle}° = ${Math.cos(t).toFixed(3)}    sin = ${Math.sin(t).toFixed(3)}`)},
integrals(){const{end,n}=this.v,xy=this.chart(0,3.2,0,10);clipped(this,()=>{const dx=end/n;for(let i=0;i<n;i++){const a=i*dx,b=(i+1)*dx,y=((i+.5)*dx)**2;this.poly([xy(a,0),xy(b,0),xy(b,y),xy(a,y)],C.amber,.18)}const pts=[];for(let x=0;x<=3.2;x+=.02)pts.push(xy(x,x*x));this.line(pts,C.mint,2.5)});footer(this,`Estimate ${midpointSquare(end,n).toFixed(4)}     Exact ${(end**3/3).toFixed(4)}`)},
limits(){const{r,n}=this.v,limit=1/(1-r),left=30,width=this.w-60,y=this.h*.43;let sum=0;for(let i=0;i<n;i++){const term=r**i,w=term/limit*width;this.poly([[left+sum/limit*width,y],[left+(sum+term)/limit*width,y],[left+(sum+term)/limit*width,y+42],[left+sum/limit*width,y+42]],i%2?C.purple:C.mint,.35);sum+=term}this.line([[left+width,y-16],[left+width,y+62]],C.white,1,[4,4]);this.text('LIMIT',left+width,y-25,C.white,11,'right');this.text(limit.toFixed(3),left+width,y+80,C.white,12,'right');this.text('0',left,y+80,C.muted,12);footer(this,`${n} terms: ${geometricSum(r,n).toFixed(4)}    Limit: ${limit.toFixed(4)}`)},
rotation(){const xy=this.chart(-3,3,-3,3),points=[[0,0],[2,1],[.5,2.5]];this.poly(points.map(p=>xy(...p)),C.muted,.02);this.poly(points.map(p=>xy(...rotate(...p,this.v.angle))),C.blue,.24);this.dot(...xy(0,0),C.mint,4);footer(this,`Rotation ${this.v.angle}°    Lengths and area stay unchanged`)},
determinant(){const{k,shear}=this.v,xy=this.chart(-3,4,-3,3);this.poly([[0,0],[1,0],[1,1],[0,1]].map(p=>xy(...p)),C.muted,.03);this.poly([[0,0],[1,0],[1+shear,k],[shear,k]].map(p=>xy(...p)),k<0?C.pink:C.mint,.25);this.arrow(xy(0,0),xy(1,0),C.blue);this.arrow(xy(0,0),xy(shear,k),C.amber);footer(this,`Signed determinant ${k.toFixed(1)}    Area ${Math.abs(k).toFixed(1)}`)},
mean(){const xs=[2,3,4,5,6,this.v.outlier],left=35,width=this.w-70,y=this.h*.43,px=v=>left+v/32*width;this.line([[left,y],[left+width,y]],C.muted);for(let i=0;i<=30;i+=5)this.text(String(i),px(i),y+30,C.muted,11,'center');xs.forEach((v,i)=>{this.line([[px(v),y],[px(v),y-20-i*5]],C.grid);this.dot(px(v),y-20-i*5,i===5?C.pink:C.blue,5)});this.line([[px(mean(xs)),y+44],[px(mean(xs)),y+75]],C.pink,3);this.line([[px(median(xs)),y+44],[px(median(xs)),y+75]],C.mint,3);footer(this,`Pink mean ${mean(xs).toFixed(2)}    Mint median ${median(xs).toFixed(2)}`)},
combinations(){const{n,k}=this.v,sets=[];function visit(start,a){if(a.length===k){sets.push(a);return}for(let i=start;i<n;i++)visit(i+1,[...a,i])}visit(0,[]);const cols=this.w<450?3:5,rows=Math.ceil(sets.length/cols),cellW=(this.w-40)/cols,cellH=Math.min(40,(this.h-100)/Math.max(1,rows));sets.forEach((set,i)=>{const x=20+(i%cols)*cellW,y=35+Math.floor(i/cols)*cellH;for(let j=0;j<n;j++)this.dot(x+8+j*(cellW-18)/n,y,set.includes(j)?C.purple:C.grid,Math.min(3,cellH*.23));if(!k)this.text('empty group',x,y+22,C.muted,11)});footer(this,`${choose(n,k)} groups    Choose ${k} of ${n}`)},
graphs(){const nodes={A:[.12,.48],B:[.4,.17],C:[.85,.28],D:[.33,.82],E:[.76,.75]},point=id=>[30+nodes[id][0]*(this.w-60),25+nodes[id][1]*(this.h-115)],edges=graphEdges(this.v.cost),result=shortestPath(edges,'A','E'),pairs=result.path.slice(1).map((x,i)=>[result.path[i],x].sort().join(''));for(const[a,b,w]of edges){const p=point(a),q=point(b),active=pairs.includes([a,b].sort().join(''));this.line([p,q],active?C.mint:C.grid,active?3:1.5);this.text(String(w),(p[0]+q[0])/2,(p[1]+q[1])/2-9,active?C.mint:C.muted,14,'center')}for(const id of Object.keys(nodes)){const p=point(id);this.dot(...p,id==='A'||id==='E'?C.mint:C.blue,7);this.text(id,p[0],p[1]-15,C.white,14,'center')}footer(this,`${result.path.join(' – ')}    Cost ${result.distance}`)},
modular(){const{n,value}=this.v,r=Math.min(this.w*.3,(this.h-120)*.4),cx=this.w/2,cy=(this.h-70)/2+12,rem=modulo(value,n);const pts=regular(n,0,r,cx,cy);this.line([...pts,pts[0]],C.grid,1);for(let i=0;i<n;i++){this.dot(...pts[i],i===rem?C.amber:C.blue,i===rem?7:3);const t=i/n*2*Math.PI-Math.PI/2;this.text(String(i),cx+Math.cos(t)*(r+19),cy+Math.sin(t)*(r+19)+4,C.muted,12,'center')}this.line([[cx,cy],pts[rem]],C.amber,2.5);footer(this,`${value} mod ${n} = ${rem}    ${Math.floor(value/n)} whole turns`)},
symmetry(){const{n,angle}=this.v,r=Math.min(this.w*.32,(this.h-100)*.43),cx=this.w/2,cy=(this.h-65)/2+12;this.poly(regular(n,0,r,cx,cy),C.muted,.02);this.poly(regular(n,angle,r,cx,cy),C.mint,.15);this.dot(...regular(n,angle,r,cx,cy)[0],C.amber,5);footer(this,`Turn ${angle}°    Repeats every ${(360/n).toFixed(2)}°`)}
};
